private static boolean isPrime(int n) {
  if (n == 1) {
    return false;
  } else if (n == 2) {
    return true;
  } else if (n % 2 == 0) {
    return false;
  } else if (n % 3 == 0) {
    return false;
  }
  int sqrt = (int)Math.sqrt(n);
  for (int i = 5; i <= sqrt; i += 6) {
    if (n % i == 0) {
      return false;
    } else if (n % (i + 2) == 0) {
      return false;
    }
  }
  return true;
}
}

