/**
 * Searches for a byte of specified value in the <code>buffer</code>, starting at the specified <code>position</code>.
 * @param buffer The buffer to search in.
 * @param value The value to find.
 * @param pos The starting position for searching.
 * @return The position of byte found, counting from the beginning of the <code>buffer</code>, or <code>-1</code> if not found.
 */
protected int findByte(ByteBuffer buffer, byte value, int pos){
  // Check if the position exceeds the buffer's limit
  if (pos >= buffer.limit()) {
    return -1;
  }

  // Check if the position exceeds the buffer's capacity
  if (pos >= buffer.capacity()) {
    return -1;
  }

  // Search for the byte in the buffer
  for (int i = pos; i < buffer.limit(); i++) {
    if (buffer.get(i) == value) {
      return i - pos;
    }
  }

  return -1;
}

