public static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    // check if graph is null
    if (graph == null) {
        throw new IllegalArgumentException("Graph cannot be null");
    }
    // check if vertices is null
    if (vertices == null) {
        throw new IllegalArgumentException("Vertices cannot be null");
    }
    // check if graph has at least as many vertices as the size of the vertex set
    if (graph.vertexSet().size() < vertices.size()) {
        throw new IllegalArgumentException("Graph does not have enough vertices");
    }
    // check if all vertices are members of the graph
    for (V vertex : vertices) {
        if (!graph.vertexSet().contains(vertex)) {
            throw new IllegalArgumentException("Vertex is not part of the graph");
        }
    }
    // check if subgraph is complete
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (!graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }
    return true;
}

